with sync_playwright() as p:
 b=p.chromium.connect_over_cdp(args.cdp) if args.cdp else p.chromium.launch();ctx=b.new_context(viewport={'width':800,'height':480});page=ctx.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(args.url);page.wait_for_function('()=>document.querySelector("#connection").textContent.includes("Connected")');page.click('[data-screen="haunt"]');page.locator('[data-open="camera-dialog"]').first.click();page.click('#camera-test');page.wait_for_selector('[data-choice="play"]',timeout=8000);assert page.locator('#visitor-dialog img,#visitor-dialog video').count()==0;page.click('[data-choice="story"]');page.click('[data-story="0"]');assert page.locator('[data-next]').count()>0;scene='Original branching story';page.click('#visitor-back');page.wait_for_function('()=>!document.querySelector("#pumpkin").disabled');snapshot=page.evaluate("async()=>{const s=await(await fetch('/api/state')).json();return {camera:s.camera,scan:s.scan.active,welcome:s.welcome,haunt:s.haunt.active};}");assert not snapshot['camera']['enabled'] and not snapshot['scan'] and not snapshot['welcome']['active'] and not snapshot['haunt'];assert not errors,errors;Path(args.output).write_text(json.dumps({'test_reveal_to_story':scene,'stop':snapshot,'errors':errors},indent=2));print(json.dumps({'scene':scene,'errors':errors}));ctx.close()
